// Runs the browser engine on cases generated by the Python engine and reports any difference.
// Usage: node tests/parity.mjs <cases.json>
import { readFileSync } from "node:fs";
import { makeEngine } from "../docs/engine.js";

const data = JSON.parse(readFileSync(new URL("../docs/data/data.json", import.meta.url)));
const cases = JSON.parse(readFileSync(process.argv[2]));
const eng = makeEngine(data.rules);
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const fails = [];

for (const c of cases.symptoms) {
  const got = eng.extractSymptoms(c.note);
  if (!same(got, c.expected)) fails.push({ kind: "symptoms", note: c.note, got, expected: c.expected });
}
for (const c of cases.interpret) {
  const got = eng.interpret(data.records[c.record].st_mv, c.sex, c.age);
  if (!same(got, c.expected)) fails.push({ kind: "interpret", ...c, got });
}
for (const c of cases.second_look) {
  const p = { ...data.patients[c.patient], history: c.history, troponin: c.troponin, symptoms: c.symptoms };
  const ecg = c.record === null ? null : eng.interpret(data.records[c.record].st_mv, p.sex, p.age);
  const r = eng.secondLook(p, c.label, ecg);
  const got = { triggered: r.triggered, level: r.level, questions: r.questions,
                findings: r.findings.map((f) => [f.level, f.text, f.action, f.ref]) };
  if (!same(got, c.expected)) fails.push({ kind: "second_look", case: c, got });
}

const total = cases.symptoms.length + cases.interpret.length + cases.second_look.length;
console.log(JSON.stringify({ total, failures: fails.length, first: fails.slice(0, 3) }, null, 1));
process.exit(fails.length ? 1 : 0);
